#!/usr/bin/env python3
"""Document the1.7.9b numeric baseline and calculate prospective regular HP."""
import collections,datetime,hashlib,html,json,math,shlex
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'docs/reports/isaac-health-balance';OUT.mkdir(exist_ok=True)
read=lambda p:json.loads((ROOT/p).read_text())
ref={r['key']:r for r in read('docs/research/isaac-mechanics-reference.json')['records'] if 'key'in r}
status=read('docs/research/isaac-enemy-port-status.json');audit=read('docs/reports/isaac-wiki-verification/audit.json');audit_rows={r['id']:r for r in audit['numeric_rows']}
profiles={};monsters={};members=set();multiplier=1
for path in sorted((ROOT/'assets/mechanics').glob('*.mechanics')):
 for line,text in enumerate(path.read_text().splitlines(),1):
  t=shlex.split(text,comments=True)
  if not t:continue
  if t[0]=='stage_health':profiles[t[1]]=dict(base=float(t[2]),stage_hp=float(t[3]),scale=float(t[4]),file=str(path.relative_to(ROOT)),line=line)
  if t[0]=='monster':monsters[t[1]]=dict(hp=float(t[6]),file=str(path.relative_to(ROOT)),line=line)
  if t[0]=='regular_health':members.add(t[1])
  if t[0]=='regular_health_multiplier':multiplier=float(t[1])
regular=[r for r in status['records'] if r['disposition']=='ordinary'];assert members=={r['id'] for r in regular}
rows=[]
for r in regular:
 key=r['id'];xml=ref[key]['xml'];p=profiles[key];base=float(xml['baseHP']);growth=float(xml['stageHP'])
 assert abs(p['base']-base)<.001 and abs(p['stage_hp']-growth)<.001
 adapt=p['scale']/3.2
 rows.append(dict(id=key,name=r['name'],source_base_hp=base,source_stage_hp=growth,conversion=3.2,adaptation=adapt,stage_one_hp=(base+growth)*p['scale']*multiplier,profile=p,wiki_result=audit_rows[key]['result'],wiki_source_conflict=audit_rows[key].get('wiki_vs_installed_xml')=='conflict'))
assert sum(abs(r['adaptation']-1)>.0001 for r in rows)==12
unmatched=[r for r in audit_rows.values() if r['result']=='no_exact_infobox'];assert len(unmatched)==14
resolutions=[]
for key in ['25.0.0','25.1.0','25.2.0','27.0.0','204.0.0']:
 r=audit_rows[key];assert r['result']=='numeric_match';resolutions.append(dict(id=key,result='edition_labels_resolved',evidence=r['snapshot_candidates']))
for r in unmatched:
 key=r['id'];xml=ref[key]['xml'];resolutions.append(dict(id=key,result='exact_xml_subtype_resolved',base_hp=float(xml['baseHP']),stage_hp=float(xml['stageHP']),scope='Numeric identity only. Shared article does not certify subtype behavior.',wiki_pages=ref[key].get('wiki_pages',[])))
resolutions.append(dict(id='817.1.0',result='wiki_conflict_resolved_in_favor_of_installed_1.7.9b',wiki_hp=13,installed_hp=14))
for r in rows:
 if abs(r['adaptation']-1)>.0001:resolutions.append(dict(id=r['id'],result='explicit_legacy_adaptation',source_base_hp=r['source_base_hp'],source_stage_hp=r['source_stage_hp'],adaptation=r['adaptation'],stage_one_hp=r['stage_one_hp']))
assert len(resolutions)==32
summary=dict(date=datetime.datetime.now(datetime.timezone.utc).isoformat(),baseline='Installed Repentance1.7.9b',scope='Source HP and balance policy; not full behavior completion.',source_reference='docs/research/isaac-mechanics-reference.json',source_reference_sha256=hashlib.sha256((ROOT/'docs/research/isaac-mechanics-reference.json').read_bytes()).hexdigest(),global_multiplier=multiplier,rows=rows,resolutions=resolutions,counts=dict(source_profiles=len(regular),legacy_adaptations=12,edition_resolutions=5,subtype_resolutions=14,wiki_conflicts_resolved=1),formula='(baseHP + stageHP * (min(sourceStage,4) + .8*clamp(sourceStage-5,0,5))) *3.2*adaptation*regular_health_multiplier',limits=['Initial/max HP normalization does not certify each enemy AI or special item interaction.','Boss body HP and unreviewed actors are excluded; regular minions remain in scope.','Neutral shot counts exclude armor, hit regions, phases, healing and weapon modifiers.','Legacy starting HP is preserved. Holy Mulligan and Cloggy now grow with source stage instead of staying flat.'])
(OUT/'baseline.json').write_text(json.dumps(summary,indent=2)+'\n')
esc=html.escape
adaptations=''.join(f'<tr><td>{r["id"]}</td><td>{esc(r["name"])}</td><td>{r["source_base_hp"]:g} + {r["source_stage_hp"]:g} × stage factor</td><td>{r["adaptation"]:.6g}×</td><td>{r["stage_one_hp"]:g}</td></tr>' for r in rows if abs(r['adaptation']-1)>.0001)
res=''.join(f'<li>{r["id"]}: {esc(r["result"].replace("_"," "))}</li>' for r in resolutions if r['result']!='explicit_legacy_adaptation')
data=json.dumps(rows).replace('<','\\u003c')
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard regular-enemy HP policy</title><style>body{{max-width:1200px;margin:auto;padding:24px;background:#1c2226;color:#eee4d2;font:16px/1.6 system-ui;overflow-wrap:anywhere}}a{{color:#91d5ca}}h1,h2,b{{color:#edc47b}}td,th{{text-align:left;padding:9px;border-bottom:1px solid #54616a}}table{{border-collapse:collapse;width:100%}}.table{{overflow:auto}}code,pre{{background:#303941;padding:6px;white-space:pre-wrap}}input,select{{font:inherit}}label{{display:block;margin:10px 0}}.note{{border-left:4px solid #edc47b;padding:12px;background:#2b3338}}li{{margin:6px 0}}</style><h1>Regular-enemy HP: source values, adaptations and testing</h1><p>{esc(summary['date'])} · <a href="baseline.json">{len(regular)} source profiles and 32 resolutions</a> · <a href="../isaac-wiki-verification/index.html">Wiki comparison</a></p><p class="note"><b>Repentance 1.7.9b is the baseline.</b> All {len(regular)} reviewed regular identities have source base HP and stage HP matching preserved XML metadata. Twelve explicit adaptation factors preserve existing starting balance. The multiplier remains <b>1</b>; no across-the-board HP reduction has been applied.</p><h2>Future HP adjustments</h2><p>Edit <a href="../../../assets/mechanics/regular_enemy_health.mechanics">assets/mechanics/regular_enemy_health.mechanics</a>:</p><pre>regular_health_multiplier 1</pre><p>For 25% less HP, use <code>regular_health_multiplier .75</code>. For half HP, use <code>.5</code>. Range: .05–4. The setting is read with the other mechanics files; restart the game and begin a new expedition to use it. Existing live snapshots retain their previous tuning.</p><p>Player defaults stay at 100 HP / 24 damage. Enemy attack damage and boss body HP are separate. Regular minions use their own regular HP settings.</p><h2>Calculation</h2><pre>HP = (source base HP + source stage HP × stage factor)
     × 3.2 conversion × explicit adaptation × regular health multiplier

stage factor = min(source stage, 4) + 0.8 × clamp(source stage − 5, 0, 5)</pre><p>The expedition floor maps to a source stage through <code>source_stages</code>; they are not interchangeable. Champion HP and offspring fractions apply once after this calculation. Supported HP regeneration, growth floors and source-health thresholds use the same balance adjustment. Attack damage does not inherit the HP multiplier.</p><p>Example: normal Charger = 20 × 3.2 = 64 HP. At .75 it has 48 HP; its Red champion has 48 × 2.6 = 124.8 HP. Neutral 24-damage shots take 2 and 6 hits respectively. Armor and phases can change actual combat results.</p><h2>Experiment calculator</h2><p>This changes this report only. It does not modify game files.</p><label>Candidate multiplier <input id="multiplier" type="range" min=".05" max="4" step=".05" value="1"><output id="amount">1.00×</output></label><label>Source stage <input id="stage" type="number" min="1" max="13" value="1"></label><label>Search <input id="search" placeholder="Enemy name or ID"></label><div class="table"><table><thead><tr><th>ID</th><th>Enemy</th><th>Current max HP</th><th>Candidate max HP</th><th>Neutral 24-damage hits</th></tr></thead><tbody id="roster"></tbody></table></div><h2>Explicit legacy adaptations</h2><p>These are deliberate balance deviations, not changed Isaac source values. Current stage-one HP is retained. Holy Mulligan and Cloggy now also retain their source stage growth; their later-stage HP therefore rises rather than remaining flat.</p><div class="table"><table><thead><tr><th>ID</th><th>Enemy</th><th>Source HP</th><th>Adaptation</th><th>Stage-one HP</th></tr></thead><tbody>{adaptations}</tbody></table></div><h2>Unclear wiki entries resolved numerically</h2><ul>{res}</ul><p>Multi-edition Boom Fly and Host values are selected by DLC labels. Subtype values use exact XML identities; a shared article is not behavior evidence for every subtype. Mullighoul uses 14 native HP, retaining the Fandom copy's conflicting 13 as source evidence.</p><h2>Validation and limits</h2><p><a href="health-tests.log">HP tests</a> check all {len(regular)} identities across 13 source stages at half HP, actual spawning, champions, unchanged player defaults/damage, regeneration floors, growth and proportional offspring/overkill. Shared controller regressions are stored alongside this report. No enemy is promoted to fully accepted on this basis.</p><ul>{''.join('<li>'+esc(v)+'</li>' for v in summary['limits'])}</ul><script>const data={data};const active={multiplier};function draw(){{const candidate=+document.querySelector('#multiplier').value,stage=Math.max(1,Math.min(13,+document.querySelector('#stage').value||1)),factor=Math.min(stage,4)+.8*Math.max(0,Math.min(stage-5,5)),q=document.querySelector('#search').value.toLowerCase();document.querySelector('#amount').textContent=candidate.toFixed(2)+'×';document.querySelector('#roster').innerHTML=data.filter(r=>(r.name+' '+r.id).toLowerCase().includes(q)).map(r=>{{const base=(r.source_base_hp+r.source_stage_hp*factor)*3.2*r.adaptation;const current=base*active,next=base*candidate;return `<tr data-id="${{r.id}}"><td>${{r.id}}</td><td>${{r.name}}</td><td>${{current.toFixed(2)}}</td><td>${{next.toFixed(2)}}</td><td>${{Math.ceil((next-1e-7)/24)}}</td></tr>`}}).join('')}};document.querySelectorAll('input').forEach(e=>e.addEventListener('input',draw));draw();</script></html>'''
(OUT/'index.html').write_text(page)
print(json.dumps(summary['counts']))
